use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION_CHARS: usize = 512;

fn push_unique(knowledge: &mut Vec<String>, entries: Vec<String>) {
    for entry in entries {
        if entry.trim().is_empty() {
            continue;
        }
        if !knowledge.iter().any(|k| *k == entry) {
            knowledge.push(entry);
        }
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;

        // The contract guarantees len(question) <= 512 on input; bound it
        // again here so the output guarantee holds regardless.
        let question: String = if inner.question.chars().count() > MAX_QUESTION_CHARS {
            inner.question.chars().take(MAX_QUESTION_CHARS).collect()
        } else {
            inner.question
        };

        let mut knowledge: Vec<String> = Vec::new();

        // Primary lookup: the question itself.
        if !question.trim().is_empty() {
            push_unique(&mut knowledge, kb_read::lookup(&question));
        }

        // Fallback: look up by extracted entities if the question found nothing.
        if knowledge.is_empty() {
            for entity in inner.entities.iter() {
                if entity.trim().is_empty() {
                    continue;
                }
                push_unique(&mut knowledge, kb_read::lookup(entity));
            }
        }

        // Ensure `knowledge` is present (non-empty) on every output.
        if knowledge.is_empty() {
            knowledge.push(String::from(
                "No knowledge base entries matched this query.",
            ));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
